import {categories,colors,equivalents,filterExpenses,aggregate,total,dailyAverage,validExpense,validTrip} from './core.js';
import {DemoStore} from './demo.js';
import {exportTripWorkbook} from './excel.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
let user={id:'demo-a'},trip={id:'local',rate:4500},members=[{user_id:'demo-a',name:'Alex'},{user_id:'demo-b',name:'Valeria'}],expenses=[],page='Inicio',currency='EUR',filters={},editing=null,busy=false,detailsId=null,demo=false;
const storageKey='travel-portfolio-unused-v1',profileKey='travel-portfolio-profile-v1';
const cloudConfigured=true;
let cloud=null,cloudState=cloudConfigured?'pending':'local',cloudMessage='',dataMode='local',cloudDevices=[],connectingCloud=false,cloudConnected=false,inviteValue='',editSnapshot=null,recordDraftKey=null;

let tripView='active',tripDraftId=null;
if(cloudConfigured)page='Viajes';
const tripName=()=>trip.name||'Mis viajes de ejemplo';
const tripCountries=()=>trip.countries?.length?trip.countries:['España','Francia'];
function tripDates(t=trip){return t.start_date&&t.end_date?new Intl.DateTimeFormat('es-CO',{day:'numeric',month:'short',year:'numeric'}).format(new Date(t.start_date+'T12:00:00'))+' — '+new Intl.DateTimeFormat('es-CO',{day:'numeric',month:'short',year:'numeric'}).format(new Date(t.end_date+'T12:00:00')):(t.name==='Mis viajes de ejemplo'||!t.name?'Fechas del viaje':'Fechas no definidas')}
const paths={home:'M3 10.5 12 3l9 7.5M5 9v12h5v-7h4v7h5V9',plus:'M12 5v14M5 12h14',history:'M7 3h10a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Zm2 5h6m-6 4h6m-6 4h4',chart:'M5 20V10m7 10V4m7 16v-7',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',wallet:'M20 8V5a2 2 0 0 0-2-2H6a3 3 0 0 0 0 6h15v11H5a3 3 0 0 1-3-3V6m19 6h-5v5h5m-3-2.5h.01',card:'M3 7h18M3 10h18M5 16h4M4 3h16a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Z',food:'M5 3v7m-3-7v5a3 3 0 0 0 6 0V3M5 11v10M17 3c-3 4-4 8 0 8h2V3h-2Zm2 8v10',transport:'M5 16h14M7 16v4m10-4v4M5 11l2-7h10l2 7M4 11h16v6H4Zm4 3h.01M16 14h.01',hotel:'M3 20V5m18 15V9H3m0 7h18M7 9V5h6v4',shopping:'M4 7h16l1 14H3L4 7Zm4 0V5a4 4 0 0 1 8 0v2',music:'M9 18V5l11-2v13M9 18a3 3 0 1 1-3-3c1 0 3 0 3 3Zm11-2a3 3 0 1 1-3-3c1 0 3 0 3 3Z',museum:'M2 9 12 3l10 6M3 10h18M5 10v9m5-9v9m4-9v9m5-9v9M2 21h20',cart:'M2 3h3l3 13h11l3-9H6m3 13h.01M18 20h.01',health:'M9 3h6v6h6v6h-6v6H9v-6H3V9h6V3Z',dots:'M5 12h.01M12 12h.01M19 12h.01',calendar:'M7 2v4m10-4v4M3 9h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2Z',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Zm-5 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',note:'M5 3h14v18H5V3Zm3 5h8m-8 4h8m-8 4h5',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',arrow:'m9 5 7 7-7 7',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',gear:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z',close:'m6 6 12 12M6 18 18 6',check:'m4 12 5 5L20 6',edit:'m15 4 5 5M3 21l4-1L21 6l-4-4L3 16v5Z',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',plane:'m2 12 8 2 3 8 2-9 7-10-10 7-10 2Z'};
const catKeys=['food','transport','hotel','shopping','music','museum','cart','health','dots'];
function icon(k,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[k]||paths.dots}"/></svg>`}
function chip(k,tone='blue'){return `<span class="iconchip ${tone}">${icon(k)}</span>`}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000)}
function money(n,c=currency){return new Intl.NumberFormat('es-ES',{style:'currency',currency:c,maximumFractionDigits:c==='COP'?0:2}).format(n)}
function name(id){return members.find(m=>m.user_id===id)?.name||'Viajero'}
function options(arr,value,empty){return (empty?`<option value="">${empty}</option>`:'')+arr.map(v=>{let [id,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`}).join('')}
let fieldId=0;
function field(label,html,wide=false){const id='field-'+(++fieldId);return `<div class="${wide?'wide':''}"><label for="${id}">${label}</label>${html.replace(/<(input|select|textarea)\b/,`<$1 id="${id}"`)}</div>`}
function navigate(p){if(cloudConfigured&&dataMode!=='cloud'&&['Inicio','Registrar gasto','Historial','Dashboard'].includes(p))p='Viajes';editing=null;editSnapshot=null;recordDraftKey=null;detailsId=null;if(p!=='Nuevo viaje')tripDraftId=null;page=p;ui();window.scrollTo(0,0)}
function ui(){fieldId=0;const rows=filterExpenses(expenses,filters),nav=[['Viajes','plane','Mis viajes'],['Inicio','home','Inicio'],['Registrar gasto','plus','Registrar'],['Historial','history','Historial'],['Dashboard','chart','Dashboard']];$('#app').innerHTML=`<div class="layout"><aside class="side"><div class="brand"><span class="brandmark">${icon('plane')}</span><div>Mis Gastos<span>de viaje</span></div></div><span class="sidecaption">NUESTROS VIAJES</span><nav>${nav.map(([n,i,l])=>`<button class="navbtn ${page===n?'active':''}" data-page="${n}" ${page===n?'aria-current="page"':''}>${icon(i)}<span>${l}</span></button>`).join('')}</nav><div class="sidefooter"><div class="tripbadge">Alex & Valeria</div><b>${esc(tripName())}</b><small>${esc(tripDates())}</small><button class="ghost" data-page="Ajustes">${icon('gear')} Ajustes del viaje</button></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">${page==='Viajes'||page==='Nuevo viaje'?'Nuestros viajes':esc(tripName())}</div><div class="toolbar"><select id="currency" class="currency" aria-label="Moneda de visualización">${options(['EUR','COP'],currency)}</select><label class="devicepicker"><span>Este dispositivo:</span><select id="profile" aria-label="Quién usa este dispositivo">${options(members.map(m=>[m.user_id,m.name]),user.id)}</select></label><button class="iconbutton" data-page="Ajustes" aria-label="Ajustes del viaje">${icon('gear')}</button></div></header>${cloudBanner()}<div class="pagecontent" data-current-page="${page}">${cloudConfigured&&dataMode==='cloud'&&!['Viajes','Nuevo viaje'].includes(page)?`<div class="trip-context"><button class="ghost" data-page="Viajes">${icon('arrow')} Mis viajes</button><span>${esc(tripName())}</span><span class="pill">${trip.status==='archived'?'Archivado':'Activo'}</span></div>`:''}${page==='Viajes'?tripsHome():page==='Nuevo viaje'?newTripForm():page==='Inicio'?home():page==='Registrar gasto'?expenseForm():page==='Historial'?history(rows):page==='Dashboard'?dashboard(rows):settings()}</div><footer class="localfooter ${dataMode==='cloud'?'cloudfooter':''}"><span class="statusdot"></span> ${esc(cloudStatus())}</footer></main></div>${detailsId?detailModal():''}`;bind();bindCloud();bindTrips()}
function skyline(){return `<svg class="skyline" viewBox="0 0 380 210" fill="none" aria-hidden="true"><ellipse cx="202" cy="193" rx="172" ry="12" fill="#d4ded5"/><circle cx="285" cy="62" r="36" fill="#f4d59e" opacity=".65"/><path d="M22 63h31c-3-15-24-15-27-4M206 43h38c-7-17-28-15-32-3M308 100h31c-4-12-21-14-25-3" fill="#fff" opacity=".65"/><path d="M266 183c18-29 27-65 31-122l4-28 4 28c4 57 13 93 31 122h-15l-20-43-20 43h-15Z" fill="#7796a0"/><path d="M285 132h32m-28-15h24m-19-38h14M273 168h56M301 30v-12" stroke="#527681" stroke-width="3"/><path d="M39 180v-55h48v55m-35-55v-18h23v18" fill="#dac4a1"/><path d="M45 127h36M50 143h7m10 0h7m-24 13h7m10 0h7" stroke="#b39b78" stroke-width="3"/><path d="M108 181V96l5-45 5 45v85m14 0V71l6-55 6 55v110m12 0V86l6-51 6 51v95m12 0v-67l5-46 5 46v67" fill="#cdac7a"/><path d="M101 181h95v-55l-10-20-10 20-13-26-14 26-13-34-13 34-12-20-10 20v55Z" fill="#ddc39d"/><path d="M126 181v-25a12 12 0 0 1 24 0v25m-36-44v12m48-12v12m16-12v12m-42-76v25m23-5v24" stroke="#a88b60" stroke-width="3"/><path d="M214 182v-47h35v47m-27-47v-13h19v13" fill="#d8c6ac"/><path d="M35 178c-10-20 9-34 19-20 1-30 32-29 31-4 18-12 32 6 20 24M189 183c-6-18 13-28 22-14 3-28 31-26 29-4 21-17 40 6 27 18M332 181c-13-18 5-36 16-20 2-21 22-20 23-1 13-1 19 14 8 21" fill="#79a397"/><path d="M47 187h318" stroke="#aec1b4" stroke-width="3"/><path d="m202 29 28-13-10 22-2-13-16 4Z" fill="#ef6b4b"/><path d="M166 25c8-10 17-14 29-12" stroke="#ef6b4b" stroke-dasharray="3 4"/></svg>`}
function home(){const rows=filterExpenses(expenses),byPerson=aggregate(rows,'payer_id',currency),t=total(rows,currency);return `<section class="welcome"><div><span class="eyebrow">NUESTRO CUADERNO DE VIAJE</span><h1>Hola, ${esc(name(user.id))}<span class="wave">☀</span></h1><p class="muted">Un viaje juntos. Cada recuerdo cuenta.</p></div><span class="tripdates">${esc(tripName())}<small>${esc(tripDates())}</small></span></section><section class="overview"><div class="totalblock"><span class="status"><span class="statusdot"></span> Nuestro viaje, hasta ahora</span><div class="totalrow"><strong>${money(t)}</strong><select id="homecurrency" class="currency" aria-label="Moneda del resumen">${options(['EUR','COP'],currency)}</select></div><span class="equivalent">≈ ${money(total(rows,currency==='EUR'?'COP':'EUR'),currency==='EUR'?'COP':'EUR')} ${currency==='EUR'?'COP':'EUR'}</span><span class="transactioncount">${rows.length} ${rows.length===1?'recuerdo registrado':'recuerdos registrados'}</span></div>${skyline()}<div class="summarygrid">${members.map((m,i)=>`<button class="summarycard personcard" data-person="${m.user_id}">${chip('user',i?'coral':'blue')}<span><small>${m.name}</small><strong>${money(byPerson[m.user_id]||0)}</strong></span>${icon('arrow','chevron')}</button>`).join('')}${[['Efectivo','wallet','mint'],['Tarjeta','card','gold']].map(([p,i,c])=>`<button class="summarycard" data-payment="${p}">${chip(i,c)}<span><small>${p}</small><strong>${money(total(rows.filter(e=>e.payment===p),currency))}</strong></span>${icon('arrow','chevron')}</button>`).join('')}</div></section><button class="primary registercta" data-page="Registrar gasto">${icon('plus')} Registrar gasto</button><div class="homebottom"><section><div class="sectionhead row"><h2>Últimos gastos</h2><button class="ghost" data-page="Historial">Ver todos ${icon('arrow')}</button></div><div class="card expensecard">${expenseList(rows.slice(0,5),false)}</div></section><section class="card journeycard"><div class="row"><span class="iconchip violet">${icon('chart')}</span><span class="pill">Una mirada al viaje</span></div><h2>Menos cuentas.<br>Más momentos.</h2><p class="muted">Descubre dónde, cómo y en qué están gastando.</p>${bars(aggregate(rows,'country',currency))}<button class="secondary" data-page="Dashboard">Ver dashboard ${icon('arrow')}</button></section></div>`}
function stats(rows){return `<div class="stats">${[['Total gastado',total(rows,currency),'wallet','coral'],['Con tarjeta',total(rows.filter(e=>e.payment==='Tarjeta'),currency),'card','gold'],['En efectivo',total(rows.filter(e=>e.payment==='Efectivo'),currency),'wallet','mint'],['Promedio diario',dailyAverage(rows,currency),'calendar','blue']].map(([l,v,i,c])=>`<section class="card stat"><div class="row"><span class="muted">${l}</span>${chip(i,c)}</div><strong>${money(v)}</strong><small>${l==='Total gastado'?rows.length+' transacciones':l==='Promedio diario'?'Entre primer y último gasto':currency}</small></section>`).join('')}</div>`}
function expenseList(rows,edit=true){return rows.length?rows.map(e=>{const ix=categories.indexOf(e.category);return `<button class="expense" data-detail="${esc(e.id)}" aria-label="Ver ${esc(e.description)}">${chip(catKeys[ix],['coral','blue','violet','gold','violet','mint','mint','coral','blue'][ix])}<span class="details"><b>${esc(e.description)}</b><small>${edit?esc(name(e.payer_id))+' · '+esc(e.payment):'Registrado por '+esc(e.created_by_name)}</small>${edit?`<small>${esc(e.city)} · ${esc(e.country)}</small>`:''}</span><span class="personbubble ${e.payer_id==='demo-b'?'sandra':''}">${esc(name(e.payer_id).slice(0,1))}</span><span class="amount"><b>${money(Number(e.amount),e.currency)}</b></span>${icon('arrow','chevron')}</button>`}).join(''):`<div class="empty"><span class="emptyicon">${icon('plane')}</span><h3>El viaje empieza aquí</h3><p>Registra ese primer café, vuelo o reserva.<br>Sus gastos aparecerán en este espacio.</p><button class="secondary" data-page="Registrar gasto">${icon('plus')} Mi primer gasto</button></div>`}
function history(rows){const groups=new Map();for(const e of rows){if(!groups.has(e.date))groups.set(e.date,[]);groups.get(e.date).push(e)}return `<div class="pageintro"><span class="eyebrow">TODO EN SU LUGAR</span><div class="row"><h1>Historial</h1><button class="iconbutton" id="exportall" aria-label="Descargar historial completo en Excel">${icon('download')}</button></div><p class="muted">${esc(tripName())}</p></div><div class="searchbox">${icon('search')}<input id="search" placeholder="Buscar gasto" aria-label="Buscar gastos" value="${esc(filters.search||'')}"></div><details class="filterdrawer" ${Object.entries(filters).some(([k,v])=>k!=='search'&&v)?'open':''}><summary>${icon('pin')} Ciudad, persona y más filtros <span class="filtercount">${Object.values(filters).filter(Boolean).length||'+'}</span></summary>${filterUI()}</details><div class="row listmeta"><small>${rows.length} movimientos · ${money(total(rows,currency))}</small><button class="ghost" id="export">${icon('download')} Exportar selección</button></div>${groups.size?[...groups].map(([date,items])=>`<section class="historygroup"><h3>${date===today()?'Hoy':new Intl.DateTimeFormat('es-ES',{weekday:'long',day:'numeric',month:'long'}).format(new Date(date+'T12:00:00'))}</h3><div class="card expensecard">${expenseList(items)}</div></section>`).join(''):`<section class="card">${expenseList([])}</section>`}`}
function formrow(key,label,control,tone='blue'){const id='input-'+key;return `<div class="formrow">${chip(key,tone)}<label for="${id}">${label}</label><div class="formcontrol">${control.replace(/<(input|select|textarea)\b/,`<$1 id="${id}"`)}</div></div>`}
function segments(key,values,current){return `<div class="segments" role="group" aria-label="${key==='currency'?'Moneda':'Método de pago'}">${values.map(v=>`<label><input type="radio" name="${key}" value="${v}" ${current===v?'checked':''}><span>${v}</span></label>`).join('')}</div>`}
function expenseForm(){if(trip.status==='archived')return '<section class="card"><h1>Viaje archivado</h1><p>Los gastos están disponibles en Historial y Dashboard. Reactiva el viaje desde Ajustes para registrar o editar.</p><button class="secondary" data-page="Historial">Ver historial</button></section>';const e=(editing?expenses.find(x=>x.id===editing):{})||{};return `<div class="pageintro"><span class="eyebrow">CADA MOMENTO CUENTA</span><h1>${editing?'Editar':'Registrar'} gasto</h1><p class="muted">Añade un gasto de tu viaje.</p></div><form id="expenseform" class="expenseform"><section class="amountentry"><div><label for="amount">Monto</label><div class="amountinput"><span id="amountsymbol">${e.currency==='COP'?'$':'€'}</span><input id="amount" name="amount" type="number" inputmode="decimal" step="0.01" min="0.01" max="1000000000000" required placeholder="0,00" value="${e.amount||''}" autofocus></div></div>${segments('currency',['EUR','COP'],e.currency||'EUR')}</section><section class="formgroup">${formrow('calendar','Fecha',`<input name="date" type="date" required value="${e.date||today()}">`,'coral')}${formrow('plane','País',`<select name="country">${options([...new Set([...tripCountries(),...(e.country?[e.country]:[])])],e.country||tripCountries()[0])}</select>`,'gold')}${formrow('pin','Ciudad',`<input name="city" list="cities" placeholder="Selecciona o escribe" maxlength="80" required value="${esc(e.city||'')}"><datalist id="cities">${[...new Set(expenses.map(e=>e.city))].sort().map(c=>`<option>${c}</option>`).join('')}</datalist>`,'blue')}${formrow('food','Categoría',`<select name="category">${options(categories,e.category||'Alimentación')}</select>`,'mint')}</section><section class="formgroup">${formrow('note','Descripción',`<input name="description" placeholder="Describe el gasto" maxlength="160" required value="${esc(e.description||'')}">`,'violet')}${formrow('card','Método de pago',segments('payment',['Efectivo','Tarjeta'],e.payment||'Tarjeta'),'gold')}${formrow('user','Persona que pagó',`<select name="payer_id">${options(members.map(m=>[m.user_id,m.name]),e.payer_id||user.id)}</select>`,'blue')}<div class="formrow">${chip('check','mint')}<span>Registrado por</span><strong>${esc(editing?e.created_by_name:name(user.id))}</strong></div>${formrow('note','Observaciones',`<textarea name="notes" maxlength="2000" placeholder="Escribe una nota… (opcional)" rows="2">${esc(e.notes||'')}</textarea>`,'slate')}</section><details class="ratedetails"><summary>Conversión aproximada <span>1 EUR = <b>${e.rate||trip.rate}</b> COP ${icon('arrow')}</span></summary><label for="rate">Tasa utilizada para este gasto</label><input id="rate" name="rate" type="number" min="0.01" max="1000000000" step="0.01" required value="${e.rate||trip.rate}"><p class="hint">Tasa manual de referencia. Quedará guardada con este gasto.</p></details><div class="formactions"><button type="submit" class="primary">${icon('check')} ${editing?'Guardar cambios':'Guardar gasto'}</button><button type="button" class="cancelbutton" id="cancel">Cancelar</button></div></form>`}
function detailModal(){const e=expenses.find(x=>x.id===detailsId);if(!e)return '';return `<div class="modalbackdrop" id="modalbackdrop"><section role="dialog" aria-modal="true" aria-labelledby="detailtitle" class="detailmodal"><div class="modalhandle"></div><div class="row">${chip(catKeys[categories.indexOf(e.category)],'coral')}<button class="iconbutton" id="closedetail" aria-label="Cerrar detalle">${icon('close')}</button></div><h2 id="detailtitle">${esc(e.description)}</h2><strong class="detailamount">${money(Number(e.amount),e.currency)}</strong><p class="muted">${esc(e.city)}, ${esc(e.country)} · ${esc(e.date)}</p><dl><div><dt>Categoría</dt><dd>${esc(e.category)}</dd></div><div><dt>Pagó</dt><dd>${esc(name(e.payer_id))} · ${esc(e.payment)}</dd></div><div><dt>Registrado por</dt><dd>${esc(e.created_by_name)}</dd></div><div><dt>Equivalente en COP</dt><dd>${money(equivalents(e).COP,'COP')}</dd></div><div><dt>Tasa guardada</dt><dd>${Number(e.rate)} COP / EUR</dd></div></dl>${e.notes?`<p class="notebox">${esc(e.notes)}</p>`:''}${trip.status!=='archived'?`<div class="modalactions"><button class="secondary" data-edit="${e.id}">${icon('edit')} Editar gasto</button><button class="deletebutton" data-delete="${e.id}">${icon('trash')} Eliminar</button></div>`:''}</section></div>`}
function settings(){return `<div class="pageintro"><span class="eyebrow">A SU MANERA</span><h1>Nuestro viaje</h1><p class="muted">Alex & Valeria · ${esc(tripName())}</p></div><section class="card settingscard"><h2>¿Quién usa este dispositivo?</h2><p class="muted">Elige tu nombre una vez. Se recuerda en este navegador y se usa al registrar gastos.</p><div class="profilecards">${members.map((m,i)=>`<button data-profile="${m.user_id}" class="profilecard ${user.id===m.user_id?'selected':''}">${chip('user',i?'coral':'blue')}<b>${m.name}</b>${user.id===m.user_id?icon('check'):''}</button>`).join('')}</div></section><form class="card settingscard" id="rateform"><h2>Conversión de monedas</h2><label for="defaultrate">1 EUR equivale a COP</label><input id="defaultrate" name="rate" type="number" step="0.01" min="0.01" max="1000000000" value="${trip.rate}" required><p class="hint">Tasa manual aproximada; 4500 es un ejemplo. Solo cambia el valor predeterminado para nuevos gastos.</p><button class="secondary">Guardar tasa</button></form>${cloudSettings()}${cloud?.multi&&dataMode==='cloud'?`<section class="card settingscard"><h2>Estado del viaje</h2><p class="muted">Archivar conserva los gastos y permite consultar y exportar el historial. Puedes reactivar el viaje cuando quieras.</p><button id="tripstatus" class="secondary">${trip.status==='archived'?'Reactivar viaje':'Archivar viaje'}</button></section>`:''}<section class="card settingscard"><h2>En la pantalla de inicio</h2><p class="muted">Cuando esté publicada con una dirección HTTPS, ábrela en Safari → Compartir → Agregar a pantalla de inicio.</p></section>`}
async function action(button,fn){if(busy)return;busy=true;if(button)button.disabled=true;try{await fn()}catch(e){toast(e.message||'No se pudo completar. Intenta de nuevo.')}finally{busy=false;if(button)button.disabled=false}}
function selectProfile(id){if(!members.some(m=>m.user_id===id))return;try{localStorage.setItem(profileKey,id);user={id};ui();toast('Este dispositivo registra como '+name(id))}catch{toast('No se pudo recordar el perfil. Revisa el almacenamiento del navegador.')}}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));if($('#currency'))$('#currency').onchange=e=>{currency=e.target.value;ui()};if($('#homecurrency'))$('#homecurrency').onchange=e=>{currency=e.target.value;ui()};if($('#profile'))$('#profile').onchange=e=>selectProfile(e.target.value);document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>selectProfile(b.dataset.profile));document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{filters={payer_id:b.dataset.person};navigate('Dashboard')});document.querySelectorAll('[data-payment]').forEach(b=>b.onclick=()=>{filters={payment:b.dataset.payment};navigate('Dashboard')});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{detailsId=b.dataset.detail;ui();$('#closedetail')?.focus()});if($('#closedetail'))$('#closedetail').onclick=()=>{detailsId=null;ui()};if($('#modalbackdrop'))$('#modalbackdrop').onclick=e=>{if(e.target.id==='modalbackdrop'){detailsId=null;ui()}};if($('#clearfilters'))$('#clearfilters').onclick=()=>{filters={};ui()};document.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{filters[el.dataset.filter]=el.value;ui()});if($('#search'))$('#search').oninput=e=>{const caret=e.target.selectionStart;filters.search=e.target.value;ui();$('#search').focus();$('#search').setSelectionRange(caret,caret)};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{editing=b.dataset.edit;editSnapshot=expenses.find(x=>x.id===editing);detailsId=null;page='Registrar gasto';ui();window.scrollTo(0,0)});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!confirm('¿Eliminar este gasto? Esta acción no se puede deshacer.'))return;action(b,async()=>{await deleteRecord(b.dataset.delete);detailsId=null;ui();toast('Gasto ficticio eliminado')})});if($('#cancel'))$('#cancel').onclick=()=>navigate('Inicio');document.querySelectorAll('input[name="currency"]').forEach(el=>el.onchange=()=>{$('#amountsymbol').textContent=el.value==='EUR'?'€':'$'});if($('#expenseform'))$('#expenseform').onsubmit=e=>{e.preventDefault();action(e.submitter,async()=>{const d=Object.fromEntries(new FormData(e.target));d.amount=Number(d.amount);d.rate=Number(d.rate);d.description=d.description.trim();d.city=d.city.trim();if(!validExpense(d)||!members.some(m=>m.user_id===d.payer_id))throw Error('Revisa el monto, la tasa y los campos obligatorios.');if(editing&&!confirm('¿Guardar los cambios de este gasto?'))return;await saveRecord(d);navigate('Historial');toast('Gasto ficticio guardado en este navegador')})};if($('#rateform'))$('#rateform').onsubmit=e=>{e.preventDefault();action(e.submitter,async()=>{const rate=Number(new FormData(e.target).get('rate'));if(!Number.isFinite(rate)||rate<=0||rate>1e9)throw Error('Tasa inválida');if(cloudConfigured){requireCloud();await cloud.rate(rate);await applyCloud(await cloud.snapshot())};toast('Tasa actualizada')})};if($('#export'))$('#export').onclick=()=>exportExcel(filterExpenses(expenses,filters));if($('#exportall'))$('#exportall').onclick=()=>exportExcel(filterExpenses(expenses),{});associateLabels()}
function associateLabels(){document.querySelectorAll('.filters input,.filters select').forEach(el=>{if(!el.id)el.id='filter-'+el.dataset.filter;const label=el.parentElement.querySelector('label');if(label)label.htmlFor=el.id})}
function init(){try{const id=localStorage.getItem(profileKey);if(members.some(m=>m.user_id===id))user={id}}catch{toast('No se pudo leer el perfil local. No se han eliminado datos.')}ui();if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('/sw.js').catch(()=>{})}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&detailsId){detailsId=null;ui()}});
window.addEventListener('storage',e=>{if(!cloudConfigured&&e.key===storageKey&&page!=='Registrar gasto')init()});
function bars(data,label=k=>k){const entries=Object.entries(data).sort((a,b)=>b[1]-a[1]),max=Math.max(1,...entries.map(e=>e[1]));return entries.length?`<div class="bars">${entries.map(([k,v],i)=>`<div><div class="barlabel"><span>${esc(label(k))}</span><b>${money(v)}</b></div><div class="track"><div class="fill" style="width:${v/max*100}%;background:${colors[i%colors.length]}"></div></div></div>`).join('')}</div>`:'<div class="empty">Todavía no hay gastos.</div>'}
function filterUI(){return `<section class="card"><div class="row" style="margin-bottom:15px"><h2 style="margin:0">Filtrar movimientos</h2><button class="ghost" id="clearfilters">Limpiar filtros</button></div><div class="filters">${field('Desde',`<input aria-label="Fecha inicial" type="date" data-filter="from" value="${esc(filters.from||'')}">`)}${field('Hasta',`<input aria-label="Fecha final" type="date" data-filter="to" value="${esc(filters.to||'')}">`)}${[['country','País',[...new Set([...tripCountries(),...expenses.map(e=>e.country)])]],['city','Ciudad',[...new Set(expenses.map(e=>e.city))].sort()],['payer_id','Persona',members.map(m=>[m.user_id,m.name])],['payment','Método de pago',['Efectivo','Tarjeta']],['category','Categoría',categories]].map(([k,l,a])=>field(l,`<select aria-label="${l}" data-filter="${k}">${options(a,filters[k],'Todos')}</select>`)).join('')}</div>${filters.from&&filters.to&&filters.from>filters.to?'<p class="notice">La fecha inicial es posterior a la final.</p>':''}</section>`}
function dashboard(rows){const data=aggregate(rows,'category',currency),entries=Object.entries(data),sum=total(rows,currency);let pos=0;const gradient=entries.map(([k,v])=>{let start=pos;pos+=sum?v/sum*100:0;return `${colors[categories.indexOf(k)]} ${start}% ${pos}%`}).join(',');const daily=aggregate(rows,'date',currency),max=Math.max(1,...Object.values(daily));return `<div class="row pageintro"><div><span class="eyebrow muted">MÁS CLARIDAD, MEJORES RECUERDOS</span><h1>El viaje en números</h1><p class="muted">Una mirada a dónde va cada ${currency==='EUR'?'euro':'peso'}.</p></div><button id="export">Descargar Excel ↓</button></div>${filterUI()}${stats(rows)}<div class="charts"><section class="card"><h2>¿En qué estamos gastando?</h2>${sum?`<div class="donutwrap"><div class="donut" role="img" aria-label="Gastos por categoría" style="background:conic-gradient(${gradient})"></div><div class="legend">${entries.map(([k,v])=>`<div class="row"><div><span style="background:${colors[categories.indexOf(k)]}"></span>${esc(k)}</div><b>${money(v)} · ${Math.round(v/sum*100)}%</b></div>`).join('')}</div></div>`:'<div class="empty">Registra un gasto para ver el gráfico.</div>'}</section><section class="card"><h2>Gastos por viajero</h2>${bars(aggregate(rows,'payer_id',currency),name)}</section><section class="card"><h2>Gastos por país</h2>${bars(aggregate(rows,'country',currency))}</section><section class="card"><h2>Efectivo y tarjeta</h2>${bars(aggregate(rows,'payment',currency))}</section><section class="card chartfull"><h2>El ritmo del viaje</h2><small>Gastos por día · ${currency}</small>${rows.length?`<div class="daychart">${Object.entries(daily).sort((a,b)=>a[0].localeCompare(b[0])).map(([d,v])=>`<div class="daycol"><span>${money(v)}</span><div class="daybar" style="height:${v/max*115}px" title="${d}: ${money(v)}"></div><span>${d.slice(8)}/${d.slice(5,7)}</span></div>`).join('')}</div>`:'<div class="empty">Sin movimientos en estas fechas.</div>'}</section><section class="card chartfull"><h2>Los lugares del viaje</h2>${bars(aggregate(rows,'city',currency))}</section></div><section class="card"><h2>Detalle de la selección</h2>${expenseList(rows,false)}</section><p class="hint">Conversión aproximada: cada gasto utiliza la tasa guardada en su registro. El promedio incluye días sin gastos entre el primer y último movimiento de la selección.</p>`}
async function exportExcel(rows,appliedFilters=filters){try{await exportTripWorkbook(rows,trip,members,appliedFilters);toast('Excel generado con '+rows.length+' gastos ficticios')}catch(e){toast(e.message||'No se pudo generar el Excel')}}

function cloudStatus(){return 'DEMO · Datos ficticios · Guardado en este navegador'}
function cloudBanner(){return '<div class="demo-banner" role="status"><strong>DEMO DE PORTAFOLIO</strong><span>Viajes y gastos ficticios. Tus cambios se guardan solo en este navegador.</span></div>'}
function cloudSettings(){return `<section class="card settingscard"><h2>Acerca de esta demostración</h2><p class="muted">Alex y Valeria son viajeros ficticios. Puedes crear viajes, registrar gastos y explorar los reportes. Los cambios son locales: no se comparten entre dispositivos.</p><p class="muted">No introduzcas información personal o financiera real en esta demo.</p><button class="secondary" id="exportall">${icon('download')} Descargar gastos de este viaje</button></section>`}
function requireCloud(){if(trip.status==='archived')throw Error('Este viaje está archivado. Reactívalo desde Ajustes para modificarlo.');if(!cloud||!cloud.tripId||dataMode!=='cloud')throw Error('Abre un viaje de demostración primero.');}
async function applyCloud(data){if(cloud?.tripId&&data.trip.id!==cloud.tripId)return;trip=data.trip;expenses=data.expenses;dataMode='cloud';cloudState='ready';cloudMessage='';if(!['Registrar gasto','Nuevo viaje'].includes(page)&&!busy)ui()}
async function connectCloud(){if(connectingCloud)return;connectingCloud=true;cloudState='pending';cloudMessage='';if(!['Registrar gasto','Nuevo viaje'].includes(page))ui();try{if(!cloud)cloud=new DemoStore();const data=await cloud.connect();await applyCloud(data);cloudDevices=[];watchCloud();cloudConnected=true}catch(e){cloudState='error';cloudMessage=e.message}finally{connectingCloud=false;if(!['Registrar gasto','Nuevo viaje'].includes(page))ui()}}
function friendlyCloudError(message){return message}
function watchCloud(){cloud.watch(async data=>{await applyCloud(data)},(state,message)=>{cloudState=state;cloudMessage=message?friendlyCloudError(message):'';if(!['Registrar gasto','Nuevo viaje','Ajustes'].includes(page)&&!busy)ui()})}
async function saveRecord(data){requireCloud();const old=editing?(editSnapshot||expenses.find(e=>e.id===editing)):null;if(!old&&!recordDraftKey)recordDraftKey=crypto.randomUUID();await cloud.save(data,name(user.id),old,old?null:'entry:'+recordDraftKey);await applyCloud(await cloud.snapshot());}
async function deleteRecord(id){requireCloud();const old=expenses.find(e=>e.id===id);if(!old)throw Error('El gasto ya no existe');await cloud.remove(old);await applyCloud(await cloud.snapshot());}
function deviceLabel(){return name(user.id)+' · '+(/iPhone|iPad/i.test(navigator.userAgent||'')?'iPhone/iPad':'PC/navegador')}
function bindCloud(){}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&cloud?.tripId)cloud.refresh()});
window.addEventListener('storage',e=>{if(e.key==='travel-portfolio-library-v1'&&cloud)cloud.refresh()});


function tripsHome(){
 const list=cloudConfigured?(cloud?.trips||[]):[{...trip,name:tripName(),status:'active'}];
 const visible=list.filter(t=>tripView==='all'||(t.status||'active')===tripView);
 const ready=cloudConfigured?(cloudConnected||cloudState==='error')&&!connectingCloud:true;
 return `<section class="trip-intro"><div><span class="eyebrow">ALEX & VALERIA</span><h1>Nuestros viajes</h1><p class="muted">Cada viaje, sus recuerdos y sus cuentas.</p></div><button class="primary" data-page="Nuevo viaje" ${!cloud?.multi||!ready?'disabled':''}>${icon('plus')} Nuevo viaje</button></section>
 ${cloudConfigured&&cloudConnected&&!cloud?.multi?'<div class="notice trip-alert">Puedes consultar tu viaje actual. Esta demostración funciona en este navegador.</div>':''}
 <div class="trip-tabs" role="group" aria-label="Mostrar viajes">${[['active','Activos'],['archived','Archivados'],['all','Todos']].map(([v,l])=>`<button data-trip-view="${v}" aria-pressed="${tripView===v}">${l} · ${list.filter(t=>v==='all'||(t.status||'active')===v).length}</button>`).join('')}<button id="refreshtrips" class="library-refresh" ${!cloud||!ready?'disabled':''}>Actualizar</button></div>
 ${!ready?'<section class="card trip-list-empty"><h2>Consultando tus viajes…</h2><p>Cargando los ejemplos guardados en este navegador.</p></section>':cloudState==='error'?`<section class="card trip-list-empty"><h2>No se pudieron actualizar los viajes</h2><p>${esc(cloudMessage)}</p><button data-page="Ajustes" class="secondary">Revisar almacenamiento</button></section>`:visible.length?`<section class="trip-grid">${visible.map(t=>`<article class="card trip-card ${t.status==='archived'?'archived':''}"><div class="row"><span class="trip-card-icon">${icon('plane')}</span><span class="pill">${t.status==='archived'?'Archivado':'Activo'}</span></div><h2>${esc(t.name||tripName())}</h2><p class="muted">${esc((t.countries||['España','Francia']).join(' · '))}</p><p>${esc(tripDates(t))}</p><small class="muted">Gastos e historial independientes</small><button class="primary" data-open-trip="${esc(t.id)}">${t.status==='archived'?'Consultar viaje':'Abrir viaje'} ${icon('arrow')}</button></article>`).join('')}</section>`:`<section class="card trip-list-empty"><h2>${tripView==='archived'?'No hay viajes archivados':'Tu próximo viaje empieza aquí'}</h2><p>${list.length?'Prueba con otro filtro para ver tus viajes.':'Crea un viaje para explorar la demostración.'}</p>${!list.length?'<button class="secondary" data-page="Ajustes">Acerca de la demo</button>':''}</section>`}`;
}
function newTripForm(){

 return `<section class="pageintro"><span class="eyebrow">UNA NUEVA AVENTURA</span><h1>Nuevo viaje</h1><p class="muted">Empieza con cero gastos. Los viajes anteriores se conservan.</p></section><form id="newtripform" class="card trip-form"><div><label for="tripname">Nombre del viaje</label><input id="tripname" name="name" maxlength="100" required placeholder="Por ejemplo: Italia 2027"></div><div class="date-fields"><div><label for="tripstart">Fecha de inicio</label><input id="tripstart" name="start_date" type="date" required></div><div><label for="tripend">Fecha de fin</label><input id="tripend" name="end_date" type="date" required></div></div><div><label for="tripcountries">Países</label><input id="tripcountries" name="countries" maxlength="2400" required placeholder="Italia, Suiza"><p class="hint">Separa los países con comas. Podrás elegirlos al registrar cada gasto.</p></div><div><label for="triprate">Tasa de referencia: COP por 1 EUR</label><input id="triprate" name="rate" type="number" step="0.01" min="0.01" max="1000000000" required value="${Number(trip.rate)||4500}"><p class="hint">Monedas disponibles: EUR y COP. Cada gasto conserva su propia tasa.</p></div><p class="notice">Este viaje se guardará únicamente en este navegador, separado de los otros viajes de ejemplo.</p><div class="formactions"><button class="primary" type="submit">${icon('plus')} Crear viaje</button><button type="button" class="secondary" data-page="Viajes">Cancelar</button></div></form>`;
}
async function openTrip(id){
 if(cloudConfigured){if(!cloud)throw Error('Revisa el almacenamiento local');await applyCloud(await cloud.open(id));inviteValue='';cloudDevices=await cloud.devices();watchCloud()}
 filters={};editing=null;editSnapshot=null;recordDraftKey=null;detailsId=null;navigate('Inicio');
}
function bindTrips(){
 document.querySelectorAll('[data-trip-view]').forEach(b=>b.onclick=()=>{tripView=b.dataset.tripView;ui()});
 document.querySelectorAll('[data-open-trip]').forEach(b=>b.onclick=()=>action(b,()=>openTrip(b.dataset.openTrip)));
 if($('#refreshtrips'))$('#refreshtrips').onclick=()=>action($('#refreshtrips'),async()=>{await connectCloud();ui()});
 if($('#newtripform'))$('#newtripform').onsubmit=e=>{e.preventDefault();action(e.submitter,async()=>{

  const d=Object.fromEntries(new FormData(e.target));d.name=d.name.trim();d.rate=Number(d.rate);d.countries=[...new Set(d.countries.split(',').map(c=>c.trim()).filter(Boolean))];
  if(!validTrip(d))throw Error('Revisa el nombre, las fechas, los países y la tasa.');
  if(!tripDraftId)tripDraftId=crypto.randomUUID();const data=await cloud.createTrip(d,deviceLabel(),tripDraftId);await applyCloud(data);cloudConnected=true;inviteValue='';cloudDevices=await cloud.devices();watchCloud();filters={};navigate('Inicio');toast('Viaje creado con cero gastos. Tus viajes anteriores se conservaron.');
 })};
 if($('#tripstatus'))$('#tripstatus').onclick=()=>action($('#tripstatus'),async()=>{
  const status=trip.status==='archived'?'active':'archived';
  if(!confirm(status==='archived'?'¿Archivar este viaje? Sus gastos se conservan y podrás consultarlos o reactivarlo.':'¿Reactivar este viaje para registrar nuevos gastos?'))return;
  await applyCloud(await cloud.setStatus(status));ui();toast(status==='archived'?'Viaje archivado. Su historial se conserva.':'Viaje reactivado');
 });
}
init();if(cloudConfigured)connectCloud();
